const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const dateTime=()=>new Date().toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'});
